from pathlib import Path
root=Path('experiments')
needles=['sait','saito','berberian','monotone sequential','monotone complete','wright','kaplansky']
for p in root.rglob('*.md'):
    text=p.read_text(errors='replace')
    lines=text.splitlines()
    hits=[(i,l) for i,l in enumerate(lines) if any(n in l.lower() for n in needles)]
    if hits:
        print('\nFILE',p)
        for i,l in hits[:15]: print(f'{i+1}: {l[:650]}')

